use std::{
    io::Write,
    path::{Component, Path, PathBuf},
    sync::Arc,
};

use base64::{engine::general_purpose::STANDARD, Engine};
use rand::{rngs::OsRng, RngCore};
use uuid::Uuid;

/// Private local storage. Keys are generated by the API, never filesystem paths
/// supplied by a client. CKW callers encrypt payloads before writing them here.
#[derive(Clone)]
pub(crate) struct LocalStorage {
    root: Arc<PathBuf>,
}

impl LocalStorage {
    pub(crate) fn new(root: PathBuf) -> std::io::Result<Self> {
        std::fs::create_dir_all(&root)?;
        Ok(Self {
            root: Arc::new(root),
        })
    }

    fn path(&self, key: &str) -> std::io::Result<PathBuf> {
        if key.is_empty()
            || !Path::new(key)
                .components()
                .all(|c| matches!(c, Component::Normal(_)))
        {
            return Err(std::io::Error::new(
                std::io::ErrorKind::InvalidInput,
                "invalid storage key",
            ));
        }
        Ok(self.root.join(key))
    }

    pub(crate) async fn put(&self, key: &str, bytes: &[u8]) -> std::io::Result<()> {
        let target = self.path(key)?;
        let parent = target.parent().expect("storage key has parent");
        tokio::fs::create_dir_all(parent).await?;
        let temporary = parent.join(format!(".{}.tmp", Uuid::new_v4()));
        let bytes = bytes.to_vec();
        tokio::task::spawn_blocking(move || {
            let result = (|| {
                let mut options = std::fs::OpenOptions::new();
                options.write(true).create_new(true);
                #[cfg(unix)]
                {
                    use std::os::unix::fs::OpenOptionsExt;
                    options.mode(0o600);
                }
                let mut file = options.open(&temporary)?;
                file.write_all(&bytes)?;
                file.sync_all()?;
                std::fs::rename(&temporary, &target)?;
                std::fs::File::open(target.parent().unwrap())?.sync_all()
            })();
            if result.is_err() {
                let _ = std::fs::remove_file(&temporary);
            }
            result
        })
        .await
        .map_err(std::io::Error::other)?
    }

    pub(crate) async fn get(&self, key: &str) -> std::io::Result<Vec<u8>> {
        tokio::fs::read(self.path(key)?).await
    }

    pub(crate) async fn delete(&self, key: &str) -> std::io::Result<()> {
        let path = self.path(key)?;
        match tokio::fs::remove_file(&path).await {
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => Ok(()),
            Err(error) => Err(error),
            Ok(()) => {
                // Persist the unlink before the database drops its retry record.
                tokio::fs::File::open(path.parent().unwrap())
                    .await?
                    .sync_all()
                    .await
            }
        }
    }

    pub(crate) async fn ready(&self) -> bool {
        let key = format!(".health-{}", Uuid::new_v4());
        self.put(&key, b"ok").await.is_ok() && self.delete(&key).await.is_ok()
    }
}

/// Publish a fully written key atomically. Existing keys are always reused;
/// invalid keys fail at validation, never silently replaced.
pub(crate) fn encryption_key(path: &Path) -> Result<String, String> {
    let parent = path
        .parent()
        .ok_or("encryption key needs a parent directory")?;
    std::fs::create_dir_all(parent).map_err(|_| "could not create key directory")?;
    if !path.exists() {
        let temporary = parent.join(format!(".key-{}", Uuid::new_v4()));
        let result = (|| -> std::io::Result<()> {
            let mut bytes = [0u8; 32];
            OsRng.fill_bytes(&mut bytes);
            let mut options = std::fs::OpenOptions::new();
            options.write(true).create_new(true);
            #[cfg(unix)]
            {
                use std::os::unix::fs::OpenOptionsExt;
                options.mode(0o600);
            }
            let mut file = options.open(&temporary)?;
            file.write_all(STANDARD.encode(bytes).as_bytes())?;
            file.sync_all()?;
            match std::fs::hard_link(&temporary, path) {
                Err(error) if error.kind() == std::io::ErrorKind::AlreadyExists => {}
                result => result?,
            }
            std::fs::File::open(parent)?.sync_all()?;
            Ok(())
        })();
        let _ = std::fs::remove_file(temporary);
        result.map_err(|_| "could not initialize encryption key")?;
    }
    std::fs::read_to_string(path)
        .map(|v| v.trim().to_string())
        .map_err(|_| "could not read encryption key".into())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[tokio::test]
    async fn storage_rejects_path_traversal_and_missing_deletion_is_idempotent() {
        let root = std::env::temp_dir().join(format!("communi-storage-{}", Uuid::new_v4()));
        let storage = LocalStorage::new(root.clone()).unwrap();
        for key in ["../outside", "/absolute", "a/../../outside", ""] {
            assert!(storage.put(key, b"secret").await.is_err());
            assert!(storage.get(key).await.is_err());
            assert!(storage.delete(key).await.is_err());
        }
        storage.delete("missing").await.unwrap();
        assert!(storage.ready().await);
        std::fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn encryption_key_is_private_and_reused_without_replacement() {
        let root = std::env::temp_dir().join(format!("communi-key-{}", Uuid::new_v4()));
        let path = root.join("key");
        let first = encryption_key(&path).unwrap();
        assert_eq!(STANDARD.decode(&first).unwrap().len(), 32);
        assert_eq!(encryption_key(&path).unwrap(), first);
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            assert_eq!(
                std::fs::metadata(&path).unwrap().permissions().mode() & 0o777,
                0o600
            );
        }
        std::fs::write(&path, "invalid").unwrap();
        assert_eq!(encryption_key(&path).unwrap(), "invalid");
        std::fs::remove_dir_all(root).unwrap();
    }
}
